    public static Cell<int> ElementThatHadNoStateWhenItsListGotIt() =>
        Cell.Loop<int>().WithoutCaptures(l => { SettableSlot x = new(); List<SettableSlot> one = [x]; x.Share = l.Map(v => v); x.Share = Plain; return S.Hold(one[0].Share!.Sample()); });

