        Cell.Loop<int>().WithoutCaptures(l => { for (int j = 0; j < 1; j++) { Cell<int>? last = null; for (int i = 0; i < 2; i++) { if (last != null) { Kept.Add(last.Sample()); } last = l.Map(v => v); } } return S.Hold(0); });

