    public static Cell<int> TurnEndsAfterItsAssignment() =>
        Cell.Loop<int>().WithoutCaptures(l => { Cell<int> last = Plain; for (int i = 0; i < 2; i++) { last = l.Map(v => v); if (i == 0) { break; } last = Plain; } return S.Hold(last.Sample()); });

