        Cell.Loop<int>().WithoutCaptures(l => { SettableSlot x = new() { Share = l.Map(v => v) }; List<SettableSlot?> list = [x, null]; x.Share = Plain; int i = Kept.Count >= 0 ? 0 : 1; return S.Hold(list[i]!.Share!.Sample()); });

