    public sealed class R4PairSetter
    {
        public Cell<int>? Share { get; set; }

        public int WriteThenRead(Cell<int> pending)
        {
            R4PairSetter[] all = [this];
            all[0].Share = Plain;
            this.Share = pending;

            return all[0].Share!.Sample();
